package org.json; import java.util.*; public class JSONObject { private final Map<String,Object> values=new LinkedHashMap<>();public JSONObject put(String k,Object v){values.put(k,v);return this;} public JSONObject put(String k,boolean v){return put(k,(Object)v);} public JSONObject put(String k,int v){return put(k,(Object)v);} public JSONObject put(String k,double v){return put(k,(Object)v);} public String toString(){return values.toString();} }
